<form class="form" data-validate novalidate method="post" action="#">
<div class="field"><label for="r-name">Имя пользователя</label><input class="inp" id="r-name" name="username" type="text" aria-describedby="r-name-err" required minlength="3" autocomplete="username"><span class="field__err" id="r-name-err" role="alert"></span></div><div class="field"><label for="r-mail">Email</label><input class="inp" id="r-mail" name="email" type="email" aria-describedby="r-mail-err" required autocomplete="email"><span class="field__err" id="r-mail-err" role="alert"></span></div><div class="field"><label for="r-pass">Пароль</label><input class="inp" id="r-pass" name="password" type="password" aria-describedby="r-pass-err" required minlength="8" autocomplete="new-password"><span class="field__err" id="r-pass-err" role="alert"></span></div><div class="field"><label for="r-pass2">Повторите пароль</label><input class="inp" id="r-pass2" name="password2" type="password" aria-describedby="r-pass2-err" required autocomplete="new-password"><span class="field__err" id="r-pass2-err" role="alert"></span></div>
<button class="btn btn--wide" type="submit">Зарегистрироваться</button><p class="form__ok" data-ok hidden>Данные заполнены верно</p></form>
<p class="auth__alt">Уже есть аккаунт? <a href="login.html">Войти</a></p>